#include <iostream>
#include <array>
#include <iomanip>

int main() {
    constexpr size_t products = 3;
    constexpr size_t salespeople = 2;

    // 3 products (rows) x 2 salespeople (columns)
    std::array<std::array<double, salespeople>, products> sales{{ 
        {120.50, 80.00},
        {200.00, 150.25},
        {50.00, 75.50}
    }};

    std::array<double, salespeople> colTotals{};
    double grandTotal = 0.0;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Prod       SP 1      SP 2     Total\n";

    for (size_t r = 0; r < products; ++r) {
        double rowTotal = 0.0;
        std::cout << "P" << (r + 1) << "   ";
        for (size_t c = 0; c < salespeople; ++c) {
            std::cout << std::setw(10) << sales[r][c];
            rowTotal += sales[r][c];
            colTotals[c] += sales[r][c];
        }
        grandTotal += rowTotal;
        std::cout << std::setw(10) << rowTotal << "\n";
    }

    std::cout << "Tot  ";
    for (size_t c = 0; c < salespeople; ++c) {
        std::cout << std::setw(10) << colTotals[c];
    }
    std::cout << std::setw(10) << grandTotal << "\n";
    return 0;
}

#include <iostream>
#include <array>

// Recursive summation (Exercise 7.17 logic)
int recursiveSum(const std::array<int, 5>& arr, size_t size) {
    if (size == 1) {
        return arr[0];
    }
    return arr[size - 1] + recursiveSum(arr, size - 1);
}

// Recursive reverse print (Exercise 7.20 logic)
void printReverse(const std::array<int, 5>& arr, size_t current) {
    if (current < arr.size()) {
        printReverse(arr, current + 1);
        std::cout << arr[current] << " ";
    }
}

int main() {
    std::array<int, 5> data = {10, 20, 30, 40, 50};

    std::cout << "Sum: " << recursiveSum(data, data.size()) << "\n";
    std::cout << "Reverse: ";
    printReverse(data, 0);
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <array>
#include <iomanip>

constexpr size_t N = 8;
const std::array<int, 8> hMove = {2, 1, -1, -2, -2, -1, 1, 2};
const std::array<int, 8> vMove = {-1, -2, -2, -1, 1, 2, 2, 1};

bool isValid(int r, int c, const std::array<std::array<int, N>, N>& board) {
    return (r >= 0 && r < static_cast<int>(N) && 
            c >= 0 && c < static_cast<int>(N) && 
            board[r][c] == 0);
}

int getAccessibility(int r, int c, const std::array<std::array<int, N>, N>& board) {
    int count = 0;
    for (size_t m = 0; m < 8; ++m) {
        if (isValid(r + vMove[m], c + hMove[m], board)) {
            ++count;
        }
    }
    return count;
}

int main() {
    std::array<std::array<int, N>, N> board{};
    int currR = 0, currC = 0;
    board[currR][currC] = 1;

    for (int moveCount = 2; moveCount <= 64; ++moveCount) {
        int minAccess = 9;
        int bestMove = -1;

        for (size_t m = 0; m < 8; ++m) {
            int nextR = currR + vMove[m];
            int nextC = currC + hMove[m];
            if (isValid(nextR, nextC, board)) {
                int access = getAccessibility(nextR, nextC, board);
                if (access < minAccess) {
                    minAccess = access;
                    bestMove = static_cast<int>(m);
                }
            }
        }

        if (bestMove == -1) break; // Dead end
        currR += vMove[bestMove];
        currC += hMove[bestMove];
        board[currR][currC] = moveCount;
    }

    // Display board
    for (size_t r = 0; r < N; ++r) {
        for (size_t c = 0; c < N; ++c) {
            std::cout << std::setw(3) << board[r][c];
        }
        std::cout << "\n";
    }
    return 0;
}
